<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use Nimbly\Capsule\Factory\RequestFactory;
use Nimbly\Capsule\Factory\StreamFactory;
use Nimbly\Capsule\Response;
use Psr\Http\Client\ClientInterface;
use Psr\Http\Message\RequestInterface;
use Psr\Http\Message\ResponseInterface;
use Psr\Log\AbstractLogger;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClient;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientSubjectTypeOptions;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientTokenEndpointAuthMethodOptions;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\Authentication\Application\BackChannelLogoutDispatcher;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Rest\LogoutController;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenSigner;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;

class LogoutEndpointTest extends OidcIntegrationTestCase
{
    private const string SESSION_ID = 'logout-session';
    private const string SSO_CLIENT = 'sso-client';
    private const string FOREIGN_CLIENT = 'foreign-client';

    /** @var array<string, TrustedClient> */
    private array $trustedClients = [];
    /** @var list<RequestInterface> */
    private array $sent = [];
    /** @var list<callable> */
    private array $jobs = [];
    /** @var list<string> */
    private array $warnings = [];

    protected function setUp(): void
    {
        parent::setUp();

        $this->register(self::CLIENT_ID, 'https://rp1.example.com/bc', 'https://rp1.example.com/fc', true);
        $this->register(self::SSO_CLIENT, 'https://rp2.example.com/bc', 'https://rp2.example.com/fc?x=1');
        $this->register(self::FOREIGN_CLIENT, 'https://foreign.example.com/bc', 'https://foreign.example.com/fc', true);

        $repository = $this->createStub(TrustedClientQueryRepositoryGateway::class);
        $repository->method('findOneByTenantAndCode')->willReturnCallback(
            fn (?TenantRef $tenant, string $code): ?TrustedClient => ($client = $this->trustedClients[$code] ?? null) !== null
                && $client->getTenant()?->uid() === $tenant?->uid() ? $client : null
        );
        $this->container->set(TrustedClientQueryRepositoryGateway::class, $repository);

        $http = new class ($this->sent) implements ClientInterface {
            /** @param list<RequestInterface> $sent */
            public function __construct(private array &$sent)
            {
            }

            public function sendRequest(RequestInterface $request): ResponseInterface
            {
                if ($request->getUri()->getHost() === 'down.example.com') {
                    throw new \RuntimeException('connection refused');
                }
                $this->sent[] = $request;
                return new Response(200);
            }
        };
        $dispatcher = new BackChannelLogoutDispatcher(
            $this->container->get(TokenSigner::class),
            $http,
            new RequestFactory(),
            new StreamFactory(),
            function (callable $job): void {
                $this->jobs[] = $job;
            },
        );
        $dispatcher->setLogger(new class ($this->warnings) extends AbstractLogger {
            /** @param list<string> $warnings */
            public function __construct(private array &$warnings)
            {
            }

            public function log($level, string|\Stringable $message, array $context = []): void
            {
                if ($level === 'warning') {
                    $this->warnings[] = $context['client'] ?? '';
                }
            }
        });
        $this->container->set(BackChannelLogoutDispatcher::class, $dispatcher);

        $this->openSession(self::SESSION_ID, $this->context->getIssuer(self::TENANT));
        $this->sessionStore->addSessionClient(self::SESSION_ID, $this->context->getIssuer(self::TENANT), self::SSO_CLIENT);
    }

    public function testOnlyParticipantsReceiveBackChannelLogoutWithoutBlockingTheResponse(): void
    {
        $sid = $this->publicSid();
        $response = $this->logout(self::SESSION_ID);

        $this->assertSame(200, $response->getStatusCode());
        $this->assertSame([], $this->sent, 'Back-channel delivery must not run before the response');

        $this->runJobs();

        $this->assertSame(['https://rp1.example.com/bc', 'https://rp2.example.com/bc'], $this->sentUris());
        foreach ($this->sent as $index => $request) {
            parse_str((string) $request->getBody(), $form);
            $claims = $this->payload($form['logout_token']);
            $this->assertSame([self::CLIENT_ID, self::SSO_CLIENT][$index], $claims['aud']);
            $this->assertSame(self::USER_ID, $claims['sub']);
            // The RPs get the session's public sid, never the cookie value.
            $this->assertSame($sid, $claims['sid']);
            $this->assertNotSame(self::SESSION_ID, $claims['sid']);
            $this->assertSame($this->context->getIssuer(self::TENANT), $claims['iss']);
        }
    }

    public function testFrontChannelListsOnlyParticipantsAddingIssAndSidWhenRequired(): void
    {
        $sid = $this->publicSid();
        $html = (string) $this->logout(self::SESSION_ID)->getBody();

        $query = http_build_query(['iss' => $this->context->getIssuer(self::TENANT), 'sid' => $sid]);
        $this->assertStringContainsString(htmlspecialchars('https://rp1.example.com/fc?' . $query), $html);
        $this->assertStringContainsString('src="https://rp2.example.com/fc?x=1"', $html);
        $this->assertStringNotContainsString('foreign.example.com', $html);
        $this->assertStringNotContainsString(self::SESSION_ID, $html);
    }

    private function publicSid(): string
    {
        return (string) $this->sessionStore->loadSession(self::SESSION_ID)?->publicSid;
    }

    public function testDisabledParticipantIsNotNotified(): void
    {
        $this->register(self::SSO_CLIENT, 'https://rp2.example.com/bc', 'https://rp2.example.com/fc', enabled: false);

        $html = (string) $this->logout(self::SESSION_ID)->getBody();
        $this->runJobs();

        $this->assertSame(['https://rp1.example.com/bc'], $this->sentUris());
        $this->assertStringNotContainsString('rp2.example.com', $html);
    }

    public function testParticipantOwnedByAnotherTenantIsNotNotified(): void
    {
        $this->register(self::SSO_CLIENT, 'https://rp2.example.com/bc', 'https://rp2.example.com/fc', tenantUid: self::TENANT_UIDS['tenant2']);

        $html = (string) $this->logout(self::SESSION_ID)->getBody();
        $this->runJobs();

        $this->assertSame(['https://rp1.example.com/bc'], $this->sentUris());
        $this->assertStringNotContainsString('rp2.example.com', $html);
    }

    public function testParticipantOwnedBySessionTenantIsNotified(): void
    {
        $this->register(self::SSO_CLIENT, 'https://rp2.example.com/bc', null, tenantUid: self::TENANT_UIDS[self::TENANT]);

        $this->logout(self::SESSION_ID);
        $this->runJobs();

        $this->assertSame(['https://rp1.example.com/bc', 'https://rp2.example.com/bc'], $this->sentUris());
    }

    public function testSessionOfAnotherTenantNotifiesNobodyAndIsKept(): void
    {
        $this->openSession('tenant2-session', $this->context->getIssuer('tenant2'));

        $response = $this->logout('tenant2-session');
        $this->runJobs();

        $this->assertSame(302, $response->getStatusCode());
        $this->assertSame([], $this->sentUris());
        $this->assertNotNull($this->sessionStore->loadSession('tenant2-session'));
    }

    public function testFailedDeliveryIsLoggedWithoutBlockingLogoutOrOtherParticipants(): void
    {
        $this->register(self::CLIENT_ID, 'https://down.example.com/bc', null);

        $response = $this->logout(self::SESSION_ID);
        $this->runJobs();

        $this->assertSame(200, $response->getStatusCode());
        $this->assertNull($this->sessionStore->loadSession(self::SESSION_ID));
        $this->assertSame(['https://rp2.example.com/bc'], $this->sentUris());
        $this->assertSame([self::CLIENT_ID], $this->warnings);
    }

    public function testInvalidRequestKeepsSessionAndNotifiesNobody(): void
    {
        foreach ([[], ['client_id' => 'unknown-client', 'post_logout_redirect_uri' => 'https://app.example.com/'], ['post_logout_redirect_uri' => 'https://app.example.com/']] as $query) {
            $response = $this->logout(self::SESSION_ID, $query);
            $this->runJobs();

            $this->assertSame(400, $response->getStatusCode());
            $this->assertNotNull($this->sessionStore->loadSession(self::SESSION_ID));
            $this->assertSame([], $this->sentUris());
        }
    }

    public function testWithoutHintTheUserConfirmsBeforeTheSessionEnds(): void
    {
        $query = ['client_id' => self::CLIENT_ID, 'post_logout_redirect_uri' => 'https://app.example.com/', 'state' => 'st'];

        $page = $this->logout(self::SESSION_ID, $query);
        $this->runJobs();

        $this->assertSame(200, $page->getStatusCode());
        $this->assertSame('no-store', $page->getHeaderLine('Cache-Control'));
        $this->assertNotNull($this->sessionStore->loadSession(self::SESSION_ID));
        $this->assertSame([], $this->sentUris());
        $html = (string) $page->getBody();
        $this->assertStringContainsString('action="http://localhost/oauth/openid/tenant1/logout"', $html);
        $this->assertStringNotContainsString(self::SESSION_ID, $html);

        $confirmed = $this->logout(self::SESSION_ID, $query + [LogoutController::CONFIRMATION_PARAM => $this->confirmationToken($html)], 'POST');

        // The participants' front-channel page, which then redirects to the RP.
        $this->assertStringContainsString('window.location.replace("https://app.example.com/?state=st")', (string) $confirmed->getBody());
        $this->assertNull($this->sessionStore->loadSession(self::SESSION_ID));
    }

    /**
     * A third party cannot confirm for the user: a token of another session, or one sent by GET,
     * only shows the confirmation page again.
     */
    public function testConfirmationOnlyCountsFromThisSessionByPost(): void
    {
        $query = ['client_id' => self::CLIENT_ID, 'post_logout_redirect_uri' => 'https://app.example.com/'];
        $this->openSession('other-session', $this->context->getIssuer(self::TENANT), 'other-csid');
        $foreignToken = $this->confirmationToken((string) $this->logout('other-session', $query)->getBody());
        $ownToken = $this->confirmationToken((string) $this->logout(self::SESSION_ID, $query)->getBody());

        foreach ([
            [$query + [LogoutController::CONFIRMATION_PARAM => $foreignToken], 'POST'],
            [$query + [LogoutController::CONFIRMATION_PARAM => ''], 'POST'],
            [$query + [LogoutController::CONFIRMATION_PARAM => $ownToken], 'GET'],
        ] as [$params, $method]) {
            $response = $this->logout(self::SESSION_ID, $params, $method);

            $this->assertSame(200, $response->getStatusCode());
            $this->assertNotNull($this->sessionStore->loadSession(self::SESSION_ID));
        }
    }

    /**
     * The cookies are removed with the path they were set with (OidcCookieManager), or the
     * browser keeps them.
     */
    public function testLogoutRemovesTheSessionCookiesWithTheirPath(): void
    {
        $cookies = $this->logout(self::SESSION_ID)->getHeader('Set-Cookie');

        $this->assertCount(2, $cookies);
        foreach ($cookies as $cookie) {
            $this->assertStringContainsString('; Path=/oauth/openid/tenant1/;', $cookie);
        }
    }

    public function testPostWithHintOfTheSessionLogsOut(): void
    {
        $response = $this->logout(self::SESSION_ID, method: 'POST');

        $this->assertSame(200, $response->getStatusCode());
        $this->assertStringContainsString('rp1.example.com/fc', (string) $response->getBody());
        $this->assertNull($this->sessionStore->loadSession(self::SESSION_ID));
    }

    /** RPs usually send the last ID token they got, long expired. */
    public function testExpiredHintIsAccepted(): void
    {
        $hint = $this->idTokenHint(self::SESSION_ID, ['iat' => time() - 7200, 'nbf' => time() - 7200, 'exp' => time() - 3600]);

        $this->logout(self::SESSION_ID, ['id_token_hint' => $hint, 'post_logout_redirect_uri' => 'https://app.example.com/']);

        $this->assertNull($this->sessionStore->loadSession(self::SESSION_ID));
    }

    public function testHintOfAnotherSessionAsksForConfirmation(): void
    {
        $hint = $this->idTokenHint(self::SESSION_ID, ['sid' => 'sid-of-an-older-session']);

        $response = $this->logout(self::SESSION_ID, ['id_token_hint' => $hint, 'post_logout_redirect_uri' => 'https://app.example.com/']);

        $this->assertSame(200, $response->getStatusCode());
        $this->assertStringContainsString(LogoutController::CONFIRMATION_PARAM, (string) $response->getBody());
        $this->assertNotNull($this->sessionStore->loadSession(self::SESSION_ID));
    }

    /**
     * @return iterable<string, array{0: array<string, mixed>, 1: array<string, string>}>
     */
    public static function invalidHints(): iterable
    {
        yield 'issued by another tenant' => [['iss' => 'http://localhost/oauth/openid/tenant2'], []];
        yield 'issued to another client' => [['aud' => self::SSO_CLIENT, 'azp' => self::SSO_CLIENT], []];
        yield 'client_id other than the hint' => [[], ['client_id' => self::SSO_CLIENT]];
        yield 'forged' => [['forged' => true], []];
    }

    /**
     * @param array<string, mixed> $claims
     * @param array<string, string> $query
     */
    #[\PHPUnit\Framework\Attributes\DataProvider('invalidHints')]
    public function testInvalidHintKeepsSessionAndNotifiesNobody(array $claims, array $query): void
    {
        $hint = $this->idTokenHint(self::SESSION_ID, $claims);
        if (isset($claims['forged'])) {
            [$header, , $signature] = explode('.', $hint);
            $payload = rtrim(strtr(base64_encode((string) json_encode(['sub' => 'attacker'] + $this->payload($hint))), '+/', '-_'), '=');
            $hint = "{$header}.{$payload}.{$signature}";
        }

        $response = $this->logout(self::SESSION_ID, $query + ['id_token_hint' => $hint, 'post_logout_redirect_uri' => 'https://app.example.com/']);
        $this->runJobs();

        $this->assertSame(400, $response->getStatusCode());
        $this->assertNotNull($this->sessionStore->loadSession(self::SESSION_ID));
        $this->assertSame([], $this->sentUris());
    }

    public function testPostLogoutRedirectMustBeRegisteredExactly(): void
    {
        foreach (['https://app.example.com', 'https://app.example.com/other', 'https://app.example.com/?next=evil'] as $uri) {
            $response = $this->logout(self::SESSION_ID, ['id_token_hint' => $this->idTokenHint(self::SESSION_ID), 'post_logout_redirect_uri' => $uri]);

            $this->assertSame(400, $response->getStatusCode(), $uri);
            $this->assertNotNull($this->sessionStore->loadSession(self::SESSION_ID));
        }
    }

    public function testWithoutSessionThereIsNothingToConfirm(): void
    {
        $response = $this->logout('', ['client_id' => self::CLIENT_ID, 'post_logout_redirect_uri' => 'https://app.example.com/']);

        $this->assertSame(302, $response->getStatusCode());
        $this->assertSame('https://app.example.com/', $response->getHeaderLine('Location'));
    }

    public function testCsidOfAnotherTenantIsNotReusedNorJoined(): void
    {
        $foreignIssuer = $this->context->getIssuer('tenant2');
        $this->openSession('tenant2-session', $foreignIssuer, 'shared-csid');

        $auth = $this->authenticateUser()->authenticate(
            new AuthenticationRequest($this->clientStore->preValidatedClient(self::TENANT, self::CLIENT_ID), 'openid', 'https://app.example.com/callback'),
            new ChallengesState(),
            self::TENANT,
            self::USERNAME,
            self::PASSWORD,
            $this->context->getIssuer(self::TENANT),
            'shared-csid',
            'state',
            'nonce'
        );

        $this->assertNotSame('tenant2-session', $auth->sessionId);
        $this->assertSame($this->context->getIssuer(self::TENANT), $this->sessionStore->loadSession($auth->sessionId)?->issuer);
        $this->assertSame([self::CLIENT_ID], $this->sessionStore->loadSession('tenant2-session')?->clients());
    }

    /**
     * Signing in again (prompt=login, max_age) on the browser of the session renews its auth_time,
     * or max_age would never be met.
     */
    public function testSigningInAgainRenewsTheAuthTimeOfTheCsidSession(): void
    {
        $this->sessionStore->authenticatedAt(self::SESSION_ID, new \DateTimeImmutable('-2 hours'));

        $auth = $this->signIn('csid');

        $this->assertSame(self::SESSION_ID, $auth->sessionId);
        $this->assertEqualsWithDelta(time(), $this->sessionStore->loadSession(self::SESSION_ID)?->authTime?->getTimestamp(), 5);
        $this->assertSame(['pwd'], $this->sessionStore->loadSession(self::SESSION_ID)?->amr);
    }

    /**
     * Another account signing in on the same browser gets a session of its own, never the
     * previous user's one.
     */
    public function testCsidSessionOfAnotherUserIsNotReused(): void
    {
        $this->sessionStore->saveSession(
            'other-user-session',
            $this->clientStore->preValidatedClient(self::TENANT, self::CLIENT_ID),
            $this->context->getIssuer(self::TENANT),
            new ChallengesState(),
            new AuthenticationResult(valid: true, id: 'other-user'),
            'shared-csid',
            new \DateInterval('P1D')
        );

        $auth = $this->signIn('shared-csid');

        $this->assertNotSame('other-user-session', $auth->sessionId);
        $this->assertSame(self::USER_ID, $this->sessionStore->loadSession($auth->sessionId)?->userId);
    }

    private function signIn(string $csid): \Civi\Lughauth\Features\OAuth\User\Domain\PublicLoginAuthResponse
    {
        return $this->authenticateUser()->authenticate(
            new AuthenticationRequest($this->clientStore->preValidatedClient(self::TENANT, self::CLIENT_ID), 'openid', 'https://app.example.com/callback'),
            new ChallengesState(),
            self::TENANT,
            self::USERNAME,
            self::PASSWORD,
            $this->context->getIssuer(self::TENANT),
            $csid,
            'state',
            'nonce'
        );
    }

    public function testAuthorizationFromSessionOfAnotherTenantIsRejectedAndDoesNotJoinIt(): void
    {
        $this->openSession('tenant2-session', $this->context->getIssuer('tenant2'));

        try {
            $this->authenticateUser()->sessionAuthenticated(
                new AuthenticationRequest(new ClientData(self::SSO_CLIENT, ['authorization_code'], true), 'openid', 'https://app.example.com/callback'),
                (new ChallengesState())->withUsername(self::USER_ID)->withSession(true),
                self::TENANT,
                $this->context->getIssuer(self::TENANT),
                'csid',
                'tenant2-session',
                'state',
                'nonce'
            );
            $this->fail('An authorization bound to a session of another tenant must be rejected');
        } catch (UnauthorizedException) {
        }

        $this->assertSame([self::CLIENT_ID], $this->sessionStore->loadSession('tenant2-session')?->clients());
    }

    private function authenticateUser(): AuthenticateUser
    {
        return $this->container->get(AuthenticateUser::class);
    }

    /**
     * @param array<string, string>|null $query logout parameters; null sends a valid request with
     *                                          an id_token_hint issued from the session
     */
    private function logout(string $sessionId, ?array $query = null, string $method = 'GET'): ResponseInterface
    {
        $query ??= ['id_token_hint' => $this->idTokenHint($sessionId), 'post_logout_redirect_uri' => 'https://app.example.com/'];
        $request = $this->makeRequest($method, '/oauth/openid/tenant1/logout')
            ->withCookieParams(['AUTH_SESSION_ID_' . strtoupper(self::TENANT) => $sessionId]);
        $request = $method === 'POST' ? $request->withParsedBody($query) : $request->withQueryParams($query);
        return $this->container->get(LogoutController::class)->logout($request, new Response(200), ['tenant' => self::TENANT]);
    }

    private function confirmationToken(string $html): string
    {
        $this->assertSame(1, preg_match('/name="' . LogoutController::CONFIRMATION_PARAM . '" value="([^"]+)"/', $html, $match));
        return $match[1];
    }

    private function runJobs(): void
    {
        foreach ($this->jobs as $job) {
            $job();
        }
        $this->jobs = [];
    }

    /** @return list<string> */
    private function sentUris(): array
    {
        return array_map(static fn (RequestInterface $request): string => (string) $request->getUri(), $this->sent);
    }

    private function payload(string $jwt): array
    {
        return json_decode(base64_decode(strtr(explode('.', $jwt)[1], '-_', '+/')), true);
    }

    private function openSession(string $sid, string $issuer, string $csid = 'csid'): void
    {
        $this->sessionStore->saveSession(
            $sid,
            $this->clientStore->preValidatedClient(self::TENANT, self::CLIENT_ID),
            $issuer,
            new ChallengesState(),
            new AuthenticationResult(valid: true, id: self::USER_ID),
            $csid,
            new \DateInterval('P1D')
        );
    }

    private function register(string $code, ?string $backChannel, ?string $frontChannel, bool $frontChannelSession = false, bool $enabled = true, ?string $tenantUid = null): void
    {
        $this->trustedClients[$code] = new TrustedClient(
            uid: $code,
            code: $code,
            tenant: $tenantUid !== null ? new TenantRef($tenantUid) : null,
            publicAllow: true,
            tokenEndpointAuthMethod: TrustedClientTokenEndpointAuthMethodOptions::CLIENT_SECRET_BASIC,
            dpopBoundAccessTokens: false,
            tlsClientCertificateBoundAccessTokens: false,
            subjectType: TrustedClientSubjectTypeOptions::PUBLIC,
            allowedRedirects: null,
            allowedAudiences: null,
            isResourceServer: false,
            requirePushedAuthorizationRequests: false,
            requirePkce: false,
            enabled: $enabled,
            m2mTokenTtlSeconds: 3600,
            backChannelLogoutUri: $backChannel,
            frontChannelLogoutUri: $frontChannel,
            frontChannelLogoutSessionRequired: $frontChannelSession,
        );
    }
}
